#!/usr/bin/env python3\nimport requests\nimport json\n\nprint(\"🚀 FIDO Server Quick Test\")\n\n# Test 1: Health check\ntry:\n    response = requests.get(\"http://localhost:8080/health\")\n    print(f\"Health: {response.status_code} - {response.json()}\")\nexcept Exception as e:\n    print(f\"Health check failed: {e}\")\n\n# Test 2: Registration options\ntry:\n    response = requests.post(\"http://localhost:8080/attestation/options\", json={\n        \"username\": \"test@example.com\",\n        \"displayName\": \"Test User\"\n    })\n    print(f\"Registration: {response.status_code}\")\n    if response.status_code == 200:\n        data = response.json()\n        print(f\"  Status: {data.get('status')}\")\n        print(f\"  Challenge length: {len(data.get('challenge', ''))}\")\n        print(f\"  Algorithms: {len(data.get('pubKeyCredParams', []))}\")\nexcept Exception as e:\n    print(f\"Registration test failed: {e}\")\n\nprint(\"\\n✅ Basic functionality verified!\")\n